// v146.22 — Manager › Turbines : pool de turbines 100LT / 20LT, attribution aux PJ ou au SAV, roue et injecteur (nom + case),
// stock virtuel par semaine. Les données vivent dans planning/turbines (un seul document).
import React, { useMemo, useState } from "react";
import { T, FZF as FZ } from "../theme";
import { getPjMeta } from "../pjMeta";
import { toLocalISO } from "../parsers";
import { useSheetJS } from "./SharedUI";
import { CARD, H_TITLE, H_SUB } from "./ManagerParts";
import { TURBINE_TYPES, parseTurbineRows, applyImport, makeTurbine, stockByWeek, summary, takenNames, targetLabel, isFree, byMad, mondayOf, addDays, isoOf, weekLabel, fmtFr, isoWeek } from "../turbines";

const todayIso = () => isoOf(new Date());
const dIso = x => { if (!x) return ""; const d = new Date(x); return isNaN(d) ? "" : toLocalISO(d); };

export function TurbinesTab({ doc, save, data, authorName, superAdmin }) {
  const turbines = useMemo(() => doc.turbines || [], [doc.turbines]), wheelNames = doc.wheelNames || [], injectorNames = doc.injectorNames || [];
  const ready = useSheetJS();
  const [filter, setFilter] = useState("all"), [typeF, setTypeF] = useState("all");
  const [pending, setPending] = useState(null), [msg, setMsg] = useState(null), [adding, setAdding] = useState(null);
  const today = todayIso();

  const rows = useMemo(() => (data || []).filter(r => r && r.pj && r.etat !== "SLOT_LIBRE"), [data]);
  const rowOf = pj => rows.find(r => r.pj === pj);
  const commit = async next => { const ok = await save({ ...doc, ...next }); if (ok === false) setMsg({ err: true, t: "L'enregistrement a échoué." }); return ok; };
  const upd = (id, patch) => commit({ turbines: turbines.map(t => t.id === id ? { ...t, ...patch } : t) });
  const sum = summary(turbines, today);

  // ── Import Excel
  const onFile = async f => {
    setMsg(null);
    try {
      if (!window.XLSX) { setMsg({ err: true, t: "Librairie Excel en cours de chargement, réessayez dans 2 s." }); return; }
      const wb = window.XLSX.read(await f.arrayBuffer(), { type: "array", cellDates: true });
      const rowsX = window.XLSX.utils.sheet_to_json(wb.Sheets[wb.SheetNames[0]], { header: 1, raw: true });
      const parsed = parseTurbineRows(rowsX);
      setPending({ name: f.name, ...parsed });
    } catch (e) { setMsg({ err: true, t: "Lecture impossible : " + e.message }); }
  };
  const confirmImport = async () => {
    const r = applyImport(turbines, pending.items);
    const ok = await commit({ turbines: r.turbines, importedAt: new Date().toISOString(), importedBy: authorName || "", importFile: pending.name });
    if (ok !== false) { setMsg({ t: "Pool mis à jour : " + r.stats.added + " ajoutée(s), " + r.stats.updated + " date(s) modifiée(s), " + r.stats.removed + " libre(s) retirée(s), " + r.stats.kept + " attribuée(s) conservée(s)." }); setPending(null); }
  };
  const template = () => {
    if (!window.XLSX) return;
    const ws = window.XLSX.utils.aoa_to_sheet([["Type", "Date MàD (ou semaine, ex. S46)", "Réf. turbine (facultatif)", "Quantité (facultatif)"], ["100LT", "S46", "", 2], ["20LT", "2026-11-10", "T-20-01", 1]]);
    ws["!cols"] = [{ wch: 10 }, { wch: 30 }, { wch: 24 }, { wch: 20 }];
    const wb = window.XLSX.utils.book_new(); window.XLSX.utils.book_append_sheet(wb, ws, "Turbines");
    window.XLSX.writeFile(wb, "Modele_import_turbines.xlsx");
  };

  // ── Stock virtuel : 12 semaines à partir de la semaine courante
  const mondays = useMemo(() => { const m0 = mondayOf(new Date()); return Array.from({ length: 12 }, (_, i) => addDays(m0, i * 7)); }, []);
  const stock = useMemo(() => stockByWeek(turbines, mondays), [turbines, mondays]);

  const list = turbines.filter(t => (typeF === "all" || t.type === typeF) && (filter === "all" || (filter === "free" ? isFree(t) : !isFree(t)))).sort(byMad);

  // ── styles
  const sel = { fontFamily: T.font, fontSize: FZ.xs, color: T.ink900, background: T.surface, border: "1px solid " + T.line, borderRadius: 8, padding: "4px 6px", maxWidth: "100%" };
  const btn = (on, primary) => ({ border: "1px solid " + (primary ? T.navy700 : on ? T.teal500 : T.line), background: primary ? T.navy700 : on ? T.teal100 : T.card, color: primary ? "#fff" : on ? T.teal600 : T.ink700, borderRadius: 999, padding: "5px 12px", fontSize: FZ.xs, fontWeight: 700, cursor: "pointer", fontFamily: T.font });
  const th = { textAlign: "left", padding: "7px 8px", fontSize: FZ.xs, fontWeight: 700, color: T.ink500, background: T.surfaceAlt, whiteSpace: "nowrap" };
  const td = { padding: "6px 8px", borderTop: "1px solid " + T.line, verticalAlign: "top", fontSize: FZ.sm };
  const warn = t => <span key={t} style={{ display: "inline-block", fontSize: FZ.xs, fontWeight: 700, color: T.amber600, background: T.amber100, borderRadius: 999, padding: "1px 8px", marginRight: 4, marginTop: 3 }}>⚠ {t}</span>;

  const targetSel = t => {
    const val = !t.target ? "" : t.target.kind === "SAV" ? "SAV" : "PJ:" + t.target.ref;
    const mine = rows.filter(r => r.etat !== "SHIPPED" || (t.target && t.target.ref === r.pj));
    const digits = t.type.replace("LT", "");
    const match = mine.filter(r => String(r.gamme || "").startsWith(digits)), other = mine.filter(r => !String(r.gamme || "").startsWith(digits));
    const opt = r => <option key={r.pj} value={"PJ:" + r.pj}>{r.pj} · {getPjMeta(r.pj, r).nomProjet || r.gamme || ""}</option>;
    return <div>
      <select value={val} aria-label={"Attribution de la turbine " + (t.ref || t.id)} onChange={e => {
        const v = e.target.value;
        upd(t.id, v === "" ? { target: null, wheel: { ...t.wheel, ok: false }, injector: { ...t.injector, ok: false } } : v === "SAV" ? { target: { kind: "SAV", ref: "" } } : { target: { kind: "PJ", ref: v.slice(3) } });
      }} style={{ ...sel, minWidth: 150, fontWeight: t.target ? 700 : 500 }}>
        <option value="">— Libre (dans le pool) —</option>
        <option value="SAV">SAV (à préciser)</option>
        {match.length > 0 && <optgroup label={"PJ en " + t.type}>{match.map(opt)}</optgroup>}
        {other.length > 0 && <optgroup label="Autres PJ">{other.map(opt)}</optgroup>}
      </select>
      {t.target && t.target.kind === "SAV" && <input value={t.target.ref} onChange={e => upd(t.id, { target: { kind: "SAV", ref: e.target.value } })} placeholder="Client / n° SAV" aria-label="Précision SAV" style={{ ...sel, marginTop: 4, width: "100%", boxSizing: "border-box" }} />}
    </div>;
  };

  const elementCell = (t, kind, names) => {
    const e = t[kind] || { name: "", ok: false };
    const taken = takenNames(turbines, kind, t.id);
    const label = kind === "wheel" ? "Roue" : "Injecteur";
    return <div style={{ display: "flex", alignItems: "center", gap: 6 }}>
      <input type="checkbox" checked={!!e.ok} disabled={!e.name || (!e.ok && taken.has(e.name))} onChange={ev => upd(t.id, { [kind]: { ...e, ok: ev.target.checked } })} aria-label={label + " réservée pour cette turbine"} title={e.ok ? "Décocher libère cet élément pour autre chose" : "Cocher quand on a la " + label.toLowerCase() + " pour cette turbine"} style={{ accentColor: T.teal600, width: 16, height: 16 }} />
      <select value={e.name || ""} onChange={ev => upd(t.id, { [kind]: { name: ev.target.value, ok: ev.target.value === e.name ? e.ok : false } })} aria-label={label + " — nom"} style={{ ...sel, minWidth: 96 }}>
        <option value="">—</option>
        {names.map(n => { const o = taken.get(n); return <option key={n} value={n} disabled={!!o}>{n}{o ? " (prise : " + (targetLabel(o) || o.ref || "autre turbine") + ")" : ""}</option>; })}
        {e.name && !names.includes(e.name) && <option value={e.name}>{e.name}</option>}
      </select>
    </div>;
  };

  const needs = t => {
    if (!t.target || t.target.kind !== "PJ") return null;
    const r = rowOf(t.target.ref); if (!r) return <span style={{ color: T.ink300, fontSize: FZ.xs }}>PJ introuvable</span>;
    const tests = dIso(r.tests), dep = dIso(r.depart), soon = isoOf(addDays(new Date(), 14));
    const W = [];
    if (t.mad && tests && t.mad > tests) W.push("MàD après le début des tests");
    if (tests && tests <= soon && !(t.wheel && t.wheel.ok)) W.push("Roue à sécuriser");
    if (dep && dep <= soon && !(t.injector && t.injector.ok)) W.push("Injecteur à sécuriser");
    return <div style={{ fontSize: FZ.xs, color: T.ink500, lineHeight: 1.4 }}>
      {tests ? <div>Tests {fmtFr(tests)} <span style={{ color: T.ink300 }}>(S{isoWeek(new Date(tests)).week})</span></div> : null}
      {dep ? <div>Départ {fmtFr(dep)}</div> : null}
      {W.map(warn)}
    </div>;
  };

  // ── catalogues roues / injecteurs
  const catalogue = (kind, names, title) => {
    const used = takenNames(turbines, kind);
    const key = kind === "wheel" ? "wheelNames" : "injectorNames";
    return <div style={{ ...CARD, padding: 14, flex: "1 1 280px" }}>
      <div style={H_TITLE}>{title}</div>
      <div style={H_SUB}>Un élément coché est réservé ; décoché, il redevient disponible.</div>
      <div style={{ display: "flex", flexWrap: "wrap", gap: 6, marginTop: 10 }}>
        {names.map(n => { const o = used.get(n); return <span key={n} style={{ display: "inline-flex", alignItems: "center", gap: 6, padding: "3px 10px", borderRadius: 999, fontSize: FZ.xs, fontWeight: 700, border: "1px solid " + (o ? T.line : T.emerald600 || T.teal500), background: o ? T.surfaceAlt : T.card, color: o ? T.ink500 : T.ink900 }}>
          {n}<span style={{ fontWeight: 600, color: o ? T.ink500 : T.emerald600 || T.teal600 }}>{o ? "→ " + (targetLabel(o) || "turbine") : "libre"}</span>
          {superAdmin && !o && <button onClick={() => commit({ [key]: names.filter(x => x !== n) })} aria-label={"Retirer " + n} title="Retirer de la liste" style={{ border: "none", background: "transparent", color: T.ink300, cursor: "pointer", padding: 0, fontSize: FZ.sm, lineHeight: 1 }}>×</button>}
        </span>; })}
        {!names.length && <span style={{ fontSize: FZ.xs, color: T.ink500 }}>Aucun nom pour l'instant.</span>}
      </div>
      <form onSubmit={e => { e.preventDefault(); const v = e.target.elements.nm.value.trim(); if (!v || names.some(x => x.toLowerCase() === v.toLowerCase())) return; commit({ [key]: [...names, v] }); e.target.reset(); }} style={{ display: "flex", gap: 6, marginTop: 10 }}>
        <input name="nm" placeholder="Ajouter un nom" aria-label={"Nouveau nom — " + title} maxLength={40} style={{ ...sel, flex: 1, padding: "6px 8px" }} />
        <button type="submit" style={btn(false)}>Ajouter</button>
      </form>
    </div>;
  };

  return (<div style={{ display: "flex", flexDirection: "column", gap: 14, fontFamily: T.font }}>
    {/* En-tête + actions */}
    <div style={{ ...CARD, padding: 16 }}>
      <div style={{ display: "flex", alignItems: "flex-start", gap: 12, flexWrap: "wrap" }}>
        <div style={{ flex: "1 1 320px" }}>
          <div style={H_TITLE}>Pool de turbines</div>
          <div style={H_SUB}>Turbines 100LT / 20LT à attribuer aux PJ ou au SAV. La roue s'installe juste avant les tests ; l'injecteur est à part mais doit être disponible pour la livraison.{doc.importedAt ? " Dernier import : " + new Date(doc.importedAt).toLocaleDateString("fr-FR") + (doc.importedBy ? " par " + doc.importedBy : "") + (doc.importFile ? " (" + doc.importFile + ")" : "") + "." : ""}</div>
        </div>
        <div style={{ display: "flex", gap: 8, flexWrap: "wrap", alignItems: "center" }}>
          <label style={{ ...btn(false, true), display: "inline-flex", alignItems: "center", gap: 6 }}>
            Importer l'Excel des turbines
            <input type="file" accept=".xlsx,.xls,.csv" style={{ display: "none" }} onChange={e => { const f = e.target.files[0]; e.target.value = ""; if (f) onFile(f); }} />
          </label>
          <button onClick={template} disabled={!ready} style={btn(false)}>Modèle Excel</button>
          <button onClick={() => setAdding(adding ? null : { type: "100LT", mad: today, ref: "" })} style={btn(!!adding)}>＋ Turbine</button>
        </div>
      </div>
      {msg && <div role="status" style={{ marginTop: 10, fontSize: FZ.xs, fontWeight: 700, color: msg.err ? T.red600 : T.emerald600 }}>{msg.t}</div>}
      {pending && <div style={{ marginTop: 12, padding: 12, border: "1px solid " + T.line, borderRadius: 10, background: T.surface }}>
        <div style={{ fontSize: FZ.sm, fontWeight: 700 }}>{pending.name} : {pending.items.length} turbine(s) lue(s) — {TURBINE_TYPES.map(ty => pending.items.filter(i => i.type === ty).length + " en " + ty).join(", ")}</div>
        <div style={{ fontSize: FZ.xs, color: T.ink500, marginTop: 4 }}>Les turbines <b>libres</b> actuelles seront remplacées par celles du fichier. Les turbines <b>attribuées</b> sont conservées (leur date est mise à jour si la réf. correspond).</div>
        {pending.errors.length > 0 && <ul style={{ margin: "6px 0 0", paddingLeft: 18, fontSize: FZ.xs, color: T.red600 }}>{pending.errors.slice(0, 8).map((e, i) => <li key={i}>{e}</li>)}{pending.errors.length > 8 && <li>… et {pending.errors.length - 8} autre(s)</li>}</ul>}
        <div style={{ display: "flex", gap: 8, marginTop: 10 }}>
          <button onClick={confirmImport} disabled={!pending.items.length} style={btn(false, true)}>Mettre à jour le pool</button>
          <button onClick={() => setPending(null)} style={btn(false)}>Annuler</button>
        </div>
      </div>}
      {adding && <form onSubmit={async e => { e.preventDefault(); if (!adding.mad) return; const ok = await commit({ turbines: [...turbines, makeTurbine(adding)].sort(byMad) }); if (ok !== false) setAdding(null); }} style={{ display: "flex", gap: 8, marginTop: 12, flexWrap: "wrap", alignItems: "center" }}>
        <select value={adding.type} onChange={e => setAdding({ ...adding, type: e.target.value })} style={sel} aria-label="Type">{TURBINE_TYPES.map(x => <option key={x}>{x}</option>)}</select>
        <input type="date" value={adding.mad} onChange={e => setAdding({ ...adding, mad: e.target.value })} aria-label="Date de MàD" style={{ ...sel, colorScheme: T.mode === "dark" ? "dark" : "light" }} />
        <input value={adding.ref} onChange={e => setAdding({ ...adding, ref: e.target.value })} placeholder="Réf. (facultatif)" aria-label="Référence" style={sel} />
        <button type="submit" style={btn(false, true)}>Ajouter</button>
      </form>}
    </div>

    {/* Tuiles */}
    <div style={{ display: "flex", gap: 12, flexWrap: "wrap" }}>
      {TURBINE_TYPES.map(ty => <div key={ty} style={{ ...CARD, padding: 14, flex: "1 1 240px" }}>
        <div style={{ fontSize: FZ.xs, fontWeight: 800, color: T.ink500, textTransform: "uppercase", letterSpacing: ".05em" }}>Turbines {ty}</div>
        <div style={{ display: "flex", gap: 18, marginTop: 8 }}>
          {[["Libres maintenant", sum[ty].libresMaintenant, T.teal600], ["Libres à venir", sum[ty].libresAVenir, T.ink700], ["Attribuées", sum[ty].attribuees, T.navy700]].map(([l, n, c]) => <div key={l}><div style={{ fontSize: FZ.xxl || 26, fontWeight: 800, color: c, lineHeight: 1 }}>{n}</div><div style={{ fontSize: FZ.xs, color: T.ink500, marginTop: 3 }}>{l}</div></div>)}
        </div>
      </div>)}
    </div>

    {/* Stock virtuel par semaine */}
    <div style={{ ...CARD, padding: 14, overflowX: "auto" }}>
      <div style={H_TITLE}>Stock virtuel par semaine</div>
      <div style={H_SUB}>« Libres » = turbines dont la MàD est passée ou à venir cette semaine-là et qui ne sont attribuées à personne (cumul).</div>
      <table style={{ borderCollapse: "collapse", marginTop: 10, minWidth: 640, width: "100%" }}>
        <thead><tr><th style={th}></th>{mondays.map(m => <th key={m.getTime()} style={{ ...th, textAlign: "center" }}>S{isoWeek(m).week}<div style={{ fontWeight: 500, color: T.ink300 }}>{String(m.getDate()).padStart(2, "0") + "/" + String(m.getMonth() + 1).padStart(2, "0")}</div></th>)}</tr></thead>
        <tbody>{TURBINE_TYPES.map(ty => [["arrivent", "Arrivent"], ["libres", "Libres (cumul)"], ["attribuees", "Attribuées (cumul)"]].map(([k, l], i) => <tr key={ty + k}>
          <td style={{ ...td, fontWeight: 700, whiteSpace: "nowrap", color: k === "libres" ? T.teal600 : T.ink700 }}>{i === 0 ? ty + " · " : "       "}{l}</td>
          {stock[ty].map((c, j) => <td key={j} style={{ ...td, textAlign: "center", fontWeight: k === "libres" ? 800 : 500, color: c[k] ? (k === "libres" ? T.teal600 : T.ink900) : T.ink300 }}>{c[k] || "·"}</td>)}
        </tr>))}</tbody>
      </table>
    </div>

    {/* Turbines */}
    <div style={{ ...CARD, overflow: "hidden" }}>
      <div style={{ padding: "12px 14px 8px", display: "flex", alignItems: "center", gap: 8, flexWrap: "wrap" }}>
        <div style={{ flex: "1 1 200px" }}><div style={H_TITLE}>Turbines et attributions</div><div style={H_SUB}>Attribuer ou ré-attribuer en direct : choisir « Libre » remet la turbine (et sa roue / son injecteur) dans le pool.</div></div>
        {[["all", "Toutes"], ["free", "Libres"], ["alloc", "Attribuées"]].map(([k, l]) => <button key={k} onClick={() => setFilter(k)} style={btn(filter === k)}>{l}</button>)}
        <span style={{ width: 1, height: 18, background: T.line }} />
        {[["all", "100 + 20"], ...TURBINE_TYPES.map(x => [x, x])].map(([k, l]) => <button key={k} onClick={() => setTypeF(k)} style={btn(typeF === k)}>{l}</button>)}
      </div>
      <div style={{ overflowX: "auto" }}>
        <table style={{ borderCollapse: "collapse", width: "100%", minWidth: 860 }}>
          <thead><tr>{["Type", "Réf.", "MàD", "Attribuée à", "Besoin du PJ", "Roue (☑ réservée)", "Injecteur (☑ réservé)", ""].map(h => <th key={h} style={th}>{h}</th>)}</tr></thead>
          <tbody>
            {list.map(t => <tr key={t.id} style={{ background: isFree(t) ? "transparent" : T.surface }}>
              <td style={{ ...td, fontWeight: 800 }}>{t.type}</td>
              <td style={td}><input defaultValue={t.ref} key={t.id + t.ref} placeholder="—" aria-label="Référence" onBlur={e => { if (e.target.value.trim() !== t.ref) upd(t.id, { ref: e.target.value.trim() }); }} style={{ ...sel, width: 84 }} /></td>
              <td style={{ ...td, whiteSpace: "nowrap" }}>
                <input type="date" value={t.mad || ""} onChange={e => upd(t.id, { mad: e.target.value })} aria-label="Date de MàD" style={{ ...sel, colorScheme: T.mode === "dark" ? "dark" : "light" }} />
                <div style={{ fontSize: FZ.xs, color: T.ink500, marginTop: 2 }}>{weekLabel(t.mad)}{t.mad && t.mad > today ? " · à venir" : t.mad ? " · disponible" : ""}</div>
              </td>
              <td style={td}>{targetSel(t)}</td>
              <td style={td}>{needs(t)}</td>
              <td style={td}>{elementCell(t, "wheel", wheelNames)}</td>
              <td style={td}>{elementCell(t, "injector", injectorNames)}</td>
              <td style={{ ...td, textAlign: "right" }}>{superAdmin && <button onClick={() => { if (window.confirm("Supprimer cette turbine du pool ?")) commit({ turbines: turbines.filter(x => x.id !== t.id) }); }} aria-label="Supprimer la turbine" title="Supprimer" style={{ border: "none", background: "transparent", color: T.red600, cursor: "pointer", fontSize: FZ.md }}>×</button>}</td>
            </tr>)}
            {!list.length && <tr><td colSpan={8} style={{ ...td, color: T.ink500, textAlign: "center", padding: 22 }}>{turbines.length ? "Aucune turbine pour ce filtre." : "Aucune turbine pour l'instant : importez l'Excel (bouton « Modèle Excel » pour le format) ou ajoutez-en une avec « ＋ Turbine »."}</td></tr>}
          </tbody>
        </table>
      </div>
    </div>

    {/* Listes roues / injecteurs */}
    <div style={{ display: "flex", gap: 12, flexWrap: "wrap" }}>
      {catalogue("wheel", wheelNames, "Roues")}
      {catalogue("injector", injectorNames, "Injecteurs")}
    </div>
  </div>);
}
